'use strict';
// Eight original, text-free settings for the early-reading course UI.
// Teaching letters, words and sound controls are supplied by the HTML engine, not these scenes.
function readingScene(theme,state={}){
 const done=!!state.done,v=Math.abs(Number(state.variant)||0)%2,ink='#405262';
 const ellipse=(x,y,rx,ry,fill)=>`<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="${fill}"/>`;
 const rect=(x,y,w,h,fill,r=8)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" fill="${fill}"/>`;
 const cloud=(x,y)=>`<g transform="translate(${x} ${y})" fill="#fffdf3"><ellipse cx="31" cy="14" rx="31" ry="12"/><circle cx="20" cy="5" r="14"/><circle cx="42" cy="7" r="12"/></g>`;
 const flower=(x,y,color='#e98b85')=>`<g transform="translate(${x} ${y})"><path d="M0 0V23M0 15q-14-13-17-3q5 10 17 7" stroke="#6c9e6d" stroke-width="3" fill="#8fba7f"/>${[0,72,144,216,288].map(a=>`<ellipse cy="-6" rx="4" ry="7" transform="rotate(${a})" fill="${color}"/>`).join('')}<circle r="4" fill="#f1d071"/></g>`;
 const bush=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})" fill="#88b99a"><circle cx="0" cy="0" r="23"/><circle cx="30" cy="-8" r="29"/><circle cx="62" cy="1" r="24"/><path d="M0 1H63V22H0Z"/></g>`;
 const leaf=(x,y,angle=0)=>`<g transform="translate(${x} ${y}) rotate(${angle})"><path d="M0 0Q-27-32 0-48Q28-31 0 0Z" fill="#75ab7b"/><path d="M0-8V-39" stroke="#4e8462" stroke-width="2"/></g>`;
 const star=(x,y,r=11,fill='#edbc56')=>`<path d="M${x} ${y-r}l${r*.32} ${r*.66} ${r*.73} ${r*.1}-${r*.53} ${r*.51} ${r*.13} ${r*.72}-${r*.65}-${r*.34}-${r*.65} ${r*.34} ${r*.13}-${r*.72}-${r*.53}-${r*.51} ${r*.73}-${r*.1}Z" fill="${fill}"/>`;
 const parcel=(x,y,w=70,h=54,color='#dbab78')=>`<g transform="translate(${x} ${y})">${rect(0,0,w,h,color,5)}<path d="M${w*.46} 1V${h}M1 ${h*.42}H${w-1}" stroke="#fff0ca" stroke-width="5"/><path d="M${w*.46} 3q-25-27-25-9q0 13 25 9q23-28 25-9q0 13-25 9" fill="none" stroke="#df8e7b" stroke-width="4" stroke-linecap="round"/></g>`;
 const boot=(x,y,w=39,angle=0)=>`<g transform="translate(${x} ${y}) rotate(${angle}) scale(${w/45})"><path d="M5 2H31V34Q35 38 44 39V53H3V38Z" fill="#d9a353" stroke="#a57943" stroke-width="2"/><path d="M5 7H31M6 48H44" stroke="#efce86" stroke-width="5"/></g>`;
 const duck=(x,y,w=58)=>`<g transform="translate(${x} ${y}) scale(${w/70})"><ellipse cx="35" cy="37" rx="31" ry="20" fill="#f3cf69"/><circle cx="49" cy="14" r="17" fill="#f3cf69"/><path d="M63 11L77 17L62 22" fill="#d79150"/><ellipse cx="27" cy="35" rx="15" ry="9" fill="#ffe39a"/><circle cx="53" cy="11" r="2.7" fill="${ink}"/><path d="M8 33L0 17L17 25" fill="#f3cf69"/></g>`;
 const envelope=(x,y,w=58)=>`<g transform="translate(${x} ${y}) scale(${w/70})">${rect(0,0,70,47,'#fff6d6',4)}<path d="M2 3L35 26L68 3M2 45L25 20M68 45L45 20" stroke="#b6a685" stroke-width="2" fill="none"/>${rect(53,7,9,12,'#88b6b2',1)}</g>`;
 const pet=(id,x,ground,w=100)=>{const dog=id==='dog',fur=dog?'#bca087':'#e4b47b',shade=dog?'#947861':'#c68d57',scale=w/120;return `<g transform="translate(${x} ${ground-109*scale}) scale(${scale})"><path d="M85 86q38 29 28-11" stroke="${fur}" stroke-width="13" fill="none" stroke-linecap="round"/><ellipse cx="61" cy="77" rx="33" ry="28" fill="${fur}"/><ellipse cx="39" cy="99" rx="16" ry="10" fill="${fur}"/><ellipse cx="80" cy="99" rx="16" ry="10" fill="${fur}"/><path d="M48 75v28M72 75v28" stroke="${shade}" stroke-width="3" fill="none"/><ellipse cx="61" cy="42" rx="34" ry="29" fill="${fur}"/>${dog?`<ellipse cx="29" cy="39" rx="10" ry="22" fill="${shade}"/><ellipse cx="93" cy="39" rx="10" ry="22" fill="${shade}"/>`:`<path d="M28 32L28 7L49 21M74 20L95 7L94 34" fill="${fur}"/><path d="M34 24V17L42 22M82 22L89 17V25" fill="#d99889"/>`}<ellipse cx="60" cy="54" rx="20" ry="14" fill="#f3dfbe"/><circle cx="47" cy="40" r="3" fill="${ink}"/><circle cx="75" cy="40" r="3" fill="${ink}"/><path d="M55 50q6-5 12 0l-6 6Z" fill="#6d5545"/><path d="M51 60q9 9 19 0" stroke="#6d5545" stroke-width="2" fill="none" stroke-linecap="round"/></g>`;};
 const friend=(id,x,ground,w=83,pose='stand')=>{const scale=w/116,base=pose==='sit'?177:151;let body;
  if(typeof friendlyAnimal==='function')body=friendlyAnimal(id,pose);
  else{const fur={cat:'#e8b77f',rabbit:'#e9ddc6',bear:'#d7ae7b',dog:'#bfa084'}[id]||'#d7ae7b';body=`<path d="M30 90H85V137H30Z" fill="#79a89b"/><path d="M39 128V151M75 128V151" stroke="${fur}" stroke-width="16"/><circle cx="57" cy="57" r="36" fill="${fur}"/><circle cx="31" cy="29" r="13" fill="${fur}"/><circle cx="83" cy="29" r="13" fill="${fur}"/><circle cx="44" cy="55" r="3" fill="${ink}"/><circle cx="71" cy="55" r="3" fill="${ink}"/><path d="M47 73q10 9 20 0" stroke="${ink}" stroke-width="2" fill="none"/>`;}
  return `<g transform="translate(${x} ${ground-base*scale}) scale(${scale})">${body}</g>`;};
 const pot=(x,y,w=52)=>`<g transform="translate(${x} ${y}) scale(${w/60})"><path d="M5 12H55L48 58H13Z" fill="#d69971"/><ellipse cx="30" cy="12" rx="27" ry="9" fill="#9d7654"/></g>`;
 const counter=(x,y,color='#ddb677')=>`<g transform="translate(${x} ${y})">${rect(0,0,235,18,color,7)}<path d="M19 18V106M215 18V106" stroke="#b18c60" stroke-width="10" stroke-linecap="round"/></g>`;
 const confetti=(x,y)=>done?`<g stroke-linecap="round" stroke-width="4" fill="none"><path d="M${x} ${y}l-5-10M${x+46} ${y-7}l6-10" stroke="#d78f9b"/><path d="M${x+18} ${y-15}v-11M${x+68} ${y+4}l10-2" stroke="#dfb14e"/><path d="M${x-19} ${y+18}l-10 3" stroke="#86b3b7"/></g>`:'';
 let b='',content='';
 if(theme==='workshop'){
  b=rect(0,0,600,280,'#e4edf0',23)+rect(0,224,600,56,'#d8bd91',0)+`<path d="M0 225H600M143 226L133 280M393 226L403 280" stroke="#c5a579" stroke-width="3"/>`;
  b+=rect(30,28,148,112,'#d1e1dc',12)+`<path d="M44 53H163M44 81H163M44 109H163" stroke="#b2ccc7" stroke-width="3"/><path d="M58 43v17m40-17v17m40-17v17M58 72v17m40-17v17m40-17v17M58 100v17m40-17v17m40-17v17" stroke="#a6c2bc" stroke-width="3"/>`;
  b+=`<path d="M70 61v32m-9 0h18M117 59l17 28m-25 4h26" stroke="#76959c" stroke-width="8" stroke-linecap="round"/>`+counter(340,133,'#c69f71');
  const rx=v?213:222;
  content=`<g transform="translate(${rx} 47)"><ellipse cx="57" cy="185" rx="60" ry="7" fill="#57706e" opacity=".13"/><path d="M26 133L20 170M81 133L91 170" stroke="#8aa5ad" stroke-width="13" stroke-linecap="round"/>${rect(4,167,34,16,'#6d8995',5)}${rect(76,167,34,16,'#6d8995',5)}<path d="M17 86L-10 105L-21 130M91 87L122 96L139 76" stroke="#8aa5ad" stroke-width="10" fill="none" stroke-linecap="round"/>${rect(15,76,81,68,'#8db8b7',14)}${rect(35,93,42,28,'#d8e7dc',8)}<circle cx="56" cy="107" r="8" fill="${done?'#e9bc58':'#a7c998'}"/>${rect(5,0,103,74,'#d6d9c5',17)}<circle cx="34" cy="30" r="10" fill="#fff8e6"/><circle cx="80" cy="30" r="10" fill="#fff8e6"/><circle cx="${done?38:34}" cy="30" r="4" fill="${ink}"/><circle cx="${done?84:80}" cy="30" r="4" fill="${ink}"/><path d="M37 54Q57 ${done?72:62} 77 54" stroke="${ink}" stroke-width="4" fill="none" stroke-linecap="round"/>${done?boot(33,-40,35,0):'<path d="M56 0V-16" stroke="#8aa5ad" stroke-width="5"/><circle cx="56" cy="-21" r="7" fill="#d79580"/>'}</g>`;
  content+=parcel(411,82,54,51,'#dba58d')+rect(475,101,39,31,'#a58dc3',5)+`<circle cx="490" cy="114" r="6" fill="#e0cee9"/>`+rect(61,193,47,30,'#e3bc67',5)+rect(109,185,38,38,'#c7a1bc',5)+confetti(rx+44,35);
 }else if(theme==='post'){
  b=rect(0,0,600,280,'#f2e7d3',23)+rect(0,220,600,60,'#d7b387',0)+rect(49,31,211,119,'#bc9c76',8);
  for(let row=0;row<2;row++)for(let col=0;col<3;col++)b+=rect(59+col*66,41+row*51,55,42,'#e9d5ac',4);
  // Separate compartment dividers keep the sorting wall readable without text.
  b+=`<path d="M59 92H249M124 42V140M190 42V140" stroke="#bc9c76" stroke-width="8"/>`+envelope(v?69:139,57,42)+envelope(v?203:73,108,42);
  content=friend(v?'cat':'rabbit',271,235,86,'hold')+counter(361,167,'#b6cbb1')+parcel(397,108,94,59)+envelope(433,174,74);
  content+=`<g transform="translate(59 187)">${rect(0,0,154,45,'#d6a16e',9)}<path d="M-7 15h-16v-28" stroke="#9a7855" stroke-width="8" fill="none" stroke-linecap="round"/><circle cx="24" cy="51" r="11" fill="#6c8184"/><circle cx="130" cy="51" r="11" fill="#6c8184"/></g>`+parcel(74,143,67,45,'#b7c9b8')+parcel(142,135,57,53,'#d8b8c9');
  if(done)content+=`<g transform="translate(445 70)"><path d="M0 38Q28 50 43 29" stroke="#c3a17d" stroke-width="10" fill="none" stroke-linecap="round"/><circle cx="-7" cy="20" r="24" fill="#e3bc75"/><path d="M-28 18q21-27 40 0q-28 25-40 0" stroke="#b68c58" stroke-width="3" fill="none"/></g>`+confetti(417,56);
 }else if(theme==='garden'){
  b=rect(0,0,600,280,v?'#e9f0dc':'#e0eef0',23)+`<circle cx="${v?493:87}" cy="54" r="27" fill="#f0cc70"/>`+cloud(193,39)+cloud(391,61)+`<path d="M0 187Q150 129 302 182Q459 132 600 181V280H0Z" fill="#bfd7ab"/><path d="M0 238Q230 182 600 226V280H0Z" fill="#d5e1b3"/>`;
  b+=bush(v?420:44,184,.9)+`<path d="M${v?77:490} 137v94" stroke="#ad8760" stroke-width="15"/>${leaf(v?79:492,144,-27)}${leaf(v?79:492,145,35)}`;
  content=`<ellipse cx="305" cy="239" rx="132" ry="12" fill="#699663" opacity=".16"/><path d="M185 220Q212 180 252 219T333 214T406 211" stroke="#8fb57d" stroke-width="29" fill="none" stroke-linecap="round"/><path d="M185 217Q212 177 252 216T333 211T406 208" stroke="#abd091" stroke-width="18" fill="none" stroke-linecap="round"/><ellipse cx="420" cy="198" rx="30" ry="27" fill="#9dc688"/><ellipse cx="413" cy="189" rx="5" ry="7" fill="#fff5d9"/><ellipse cx="435" cy="187" rx="5" ry="7" fill="#fff5d9"/><circle cx="415" cy="191" r="2.7" fill="${ink}"/><circle cx="437" cy="189" r="2.7" fill="${ink}"/><path d="M422 210q15 4 20-5" stroke="#58734f" stroke-width="2.5" fill="none" stroke-linecap="round"/>`;
  content+=flower(83,221,'#d493ad')+flower(140,230,'#e6b64b')+flower(489,228,'#c39bc7')+flower(545,225,'#e58a7a')+pot(280,232,43)+leaf(301,240,0);
  if(done)content+=`<path d="M397 179Q426 151 451 177L441 182H401Z" fill="#6d9d76"/><path d="M425 175L441 151" stroke="#6d9d76" stroke-width="3"/>`+confetti(411,140);
 }else if(theme==='sound'){
  b=rect(0,0,600,280,'#e5eff0',23)+cloud(65,42)+cloud(440,46)+`<circle cx="338" cy="47" r="23" fill="#f0cc70"/><path d="M0 135Q150 103 600 143V280H0Z" fill="#c3d5ae"/><path d="M187 116Q305 144 407 109L477 280H121Z" fill="#9ecbd0"/><path d="M234 153q70 10 124-3M206 244q102 12 178-2" fill="none" stroke="#d7eeea" stroke-width="7" stroke-linecap="round"/>`;
  const stones=v?[[170,216],[264,181],[360,147],[438,208]]:[[172,215],[269,186],[370,163],[443,218]];
  content=stones.map(([x,y],i)=>`<ellipse cx="${x}" cy="${y+6}" rx="39" ry="14" fill="#8ca4a1"/><ellipse cx="${x}" cy="${y}" rx="39" ry="14" fill="${i===1?'#d4c292':'#dbe1ca'}"/>`).join('');
  content+=friend('rabbit',24,240,76)+flower(94,230,'#d58fa8')+bush(494,218,.8);
  content+=done?duck(stones[2][0]-26,stones[2][1]-44,52)+confetti(365,83):duck(v?316:299,224,46);
 }else if(theme==='slide'){
  b=rect(0,0,600,280,'#f4ead9',23)+cloud(65,35)+cloud(370,40)+`<circle cx="518" cy="53" r="24" fill="#ebc268"/><path d="M0 207Q150 150 312 202Q459 173 600 208V280H0Z" fill="#c6d9ac"/>`;
  content=`<path d="M151 90V240M112 119H161M112 155H161M112 191H161M112 227H161M112 102V240" stroke="#a58b68" stroke-width="9" fill="none" stroke-linecap="round"/><path d="M158 88Q230 95 267 161Q300 222 419 223" stroke="#c78668" stroke-width="28" fill="none" stroke-linecap="round"/><path d="M158 79Q231 87 269 151Q305 215 422 214" stroke="#efbd71" stroke-width="28" fill="none" stroke-linecap="round"/><path d="M157 72Q235 78 274 144Q308 206 423 207" stroke="#ffe1a5" stroke-width="7" fill="none" stroke-linecap="round"/><path d="M408 213v28M184 108v130M283 178v62" stroke="#a58b68" stroke-width="9"/>`;
  content+=ellipse(464,244,69,16,'#d8c998')+flower(48,232,'#d593ac')+flower(550,228,'#dca65a');
  // The duck is seated directly on the slide surface or on the landing mat.
  content+=done?duck(438,203,58)+confetti(477,175):duck(v?204:139,v?91:39,54);
  if(done&&v)content+=boot(517,196,26,-13);
 }else if(theme==='machine'){
  b=rect(0,0,600,280,v?'#e9e5ed':'#e1eded',23)+rect(0,228,600,52,'#d6bb95',0)+rect(41,31,153,92,'#d0ddd5',10)+`<path d="M57 56h120M57 81h120M57 106h120" stroke="#b5c7ba" stroke-width="4"/>`;
  content=`<g transform="translate(257 55)"><path d="M6 178v20M209 178v20" stroke="#8f8a83" stroke-width="11" stroke-linecap="round"/>${rect(0,0,220,178,'#9db9bb',20)}${rect(24,24,172,57,'#f9eed4',10)}<path d="M49 52h122" stroke="#d2d9bf" stroke-width="10" stroke-linecap="round"/>${rect(19,105,182,50,'#637f8c',8)}${rect(30,114,160,30,'#adc2c0',5)}<circle cx="36" cy="90" r="8" fill="#e5af61"/><circle cx="63" cy="90" r="8" fill="#c88897"/><path d="M219 64h26v62" stroke="#839b9f" stroke-width="10" fill="none" stroke-linecap="round"/><circle cx="245" cy="129" r="13" fill="#d7aa6e"/></g>`;
  content+=friend(v?'dog':'bear',99,244,82,'hold')+parcel(34,196,46,47,'#d9b27d');
  if(done)content+=`<path d="M290 175H442V235H290Z" fill="#fbf1d7" stroke="#a7b7b3" stroke-width="2"/>`+star(315,206,13)+ellipse(364,206,15,15,'#cf9a9d')+boot(399,181,28,3)+confetti(356,26);
  else content+=`<path d="M308 169H425V192H308Z" fill="#e9dfc9"/>`;
 }else if(theme==='village'){
  b=rect(0,0,600,280,'#e7f0ed',23)+cloud(54,37)+cloud(467,46)+`<path d="M0 220Q179 190 600 220V280H0Z" fill="#c5d6ad"/><path d="M0 247Q307 206 600 244V280H0Z" fill="#e7d4ad"/>`;
  content=`<g transform="translate(39 74)"><path d="M0 60L75 0L150 60Z" fill="#be8175"/>${rect(12,58,126,111,'#edc99b',4)}${rect(31,78,35,43,'#a4c6c4',5)}<path d="M48 79v42M32 101h33" stroke="#ffefd4" stroke-width="3"/>${rect(86,91,32,78,'#91b2a5',5)}<circle cx="110" cy="132" r="3" fill="#d0a25f"/></g>`;
  content+=`<g transform="translate(295 56)">${rect(0,38,223,150,'#e7be8e',7)}<path d="M-10 44H233L213 0H11Z" fill="#a8c1b2"/><path d="M25 0L12 44M74 0L68 44M124 0L124 44M174 0L181 44M214 0L232 44" stroke="#f9edcf" stroke-width="19"/>${rect(24,78,112,59,'#bad5cd',4)}${rect(158,74,41,114,'#8caaa0',5)}<circle cx="190" cy="132" r="3" fill="#e1b76a"/>${rect(16,143,128,15,'#b78d62',4)}<path d="M27 157v31M133 157v31" stroke="#b78d62" stroke-width="8"/></g>`;
  content+=parcel(326,155,44,44,'#e4aa84')+parcel(377,165,41,34,'#b6c69f')+friend(v?'cat':'rabbit',209,244,69,'hold');
  if(done)content+=duck(482,207,48)+confetti(483,176);else content+=bush(546,215,.6);
 }else{
  // Story: a cat has a supported mat; the second setting is a puppy picnic.
  b=rect(0,0,600,280,v?'#f1e9d7':'#e8eff0',23);
  if(v){b+=cloud(77,39)+cloud(425,32)+`<circle cx="325" cy="42" r="23" fill="#edcc76"/><path d="M0 177Q190 130 600 183V280H0Z" fill="#bfd5aa"/>`+bush(445,164,.95);content+=`<path d="M99 195L403 179L477 254H126Z" fill="#dfa298"/><path d="M141 193l46 57M220 190l45 59M300 186l43 59M375 182l41 61M109 218l334-5M121 241l345-4" stroke="#f9e4cd" stroke-width="9"/>`;content+=pet(state.object==='cat'?'cat':'dog',136,232,86)+parcel(325,187,65,49,'#d3b47d')+envelope(267,205,47)+flower(526,224,'#d99cbd');if(done)content+=`<g transform="translate(404 135) rotate(17 20 40)"><path d="M21 46V108" stroke="#b6c3c6" stroke-width="12" stroke-linecap="round"/><ellipse cx="21" cy="24" rx="20" ry="28" fill="#cad6d5" stroke="#95aeb3" stroke-width="3"/></g>`+confetti(387,116);}
  else{b+=rect(0,204,600,76,'#d9bd96',0)+rect(428,33,112,104,'#b3d0cb',9)+`<path d="M484 33v104M428 86h112" stroke="#fff4dc" stroke-width="7"/><path d="M0 205H600M158 205L143 280M411 205L425 280" stroke="#c7a57b" stroke-width="3"/>`;
   content+=ellipse(273,238,157,25,'#acb7cc')+ellipse(273,234,145,19,'#d4d7e0')+pet(state.object==='dog'?'dog':'cat',230,234,105);content+=`<path d="M70 127H144V231H70Z" fill="#d3a36f"/><path d="M64 126H150" stroke="#ae8057" stroke-width="9"/>`+pot(87,103,40)+leaf(107,115,-17)+leaf(108,115,24);if(done)content+=duck(366,191,55)+confetti(362,155);else content+=ellipse(378,222,18,18,'#e6bd69')+`<path d="M363 211q22 6 30 21" stroke="#be9654" stroke-width="2" fill="none"/>`;}
 }
 return `<svg xmlns="http://www.w3.org/2000/svg" class="reading-scene" viewBox="0 0 600 280" aria-hidden="true" focusable="false"><g stroke-linejoin="round" stroke-linecap="round">${b}${content}</g></svg>`;
}
